ST.xhtml:
IF error_in AND state <> 3 THEN
    state := 3;                          // ERROR forced from any state
ELSIF state = 0 THEN                     // PAUSE
    IF s1_start THEN
        state := 1;
    ELSIF s4_reset THEN
        state := 2;
    END_IF;
ELSIF state = 1 THEN                     // RUN
    IF s2_stop THEN state := 0; END_IF;  // S4 ignored here
ELSIF state = 2 THEN                     // RESET
    IF s2_stop OR reset_done THEN state := 0; END_IF;   // S1 ignored here
ELSIF state = 3 THEN                     // ERROR
    IF s4_reset THEN state := 2; END_IF; // clears fault, begins reset/homing
END_IF;

run_mode    := (state = 1);
pause_mode  := (state = 0);
reset_mode  := (state = 2);
error_mode  := (state = 3);
start_light := run_mode;
reset_light := reset_mode;

CASE state OF
0:  (* AT_HOME *)
    IF error_mode THEN state := 4;
    ELSIF reset_mode THEN
        IF NOT sensor_home THEN state := 3; END_IF;
    ELSIF run_mode AND go THEN
        state := 1;
    END_IF;
1:  (* TO_END *)
    IF error_mode THEN state := 4;
    ELSIF reset_mode THEN state := 3;          // abort stroke, go home
    ELSIF pause_mode THEN ;                     // freeze in place
    ELSIF sensor_end THEN state := 2;
    END_IF;
2:  (* AT_END *)
    IF error_mode THEN state := 4;
    ELSIF reset_mode THEN state := 3;
    ELSIF run_mode AND go THEN state := 3;      // continuous cycle
    END_IF;
3:  (* TO_HOME *)
    IF error_mode THEN state := 4;
    ELSIF pause_mode AND NOT reset_mode THEN ;  // freeze (reset overrides pause)
    ELSIF sensor_home THEN state := 0;
    END_IF;
4:  (* ERROR -- valves off, recover only via reset sequence *)
    IF reset_mode THEN
        IF sensor_home THEN state := 0; ELSE state := 3; END_IF;
    END_IF;
END_CASE;

// Valves derive from the final state; pause zeroes them (hold in place).
valve_to_end  := (state = 1) AND NOT pause_mode;
valve_to_home := (state = 3) AND NOT pause_mode;

// Stall detection: commanding a valve but not arriving.
moving := valve_to_end OR valve_to_home;
stall(IN := robust AND moving, PT := t_stall);
IF stall.Q THEN state := 4; END_IF;

IF state = 4 THEN
    valve_to_end := FALSE;
    valve_to_home := FALSE;
END_IF;

at_home := (state = 0);
to_end  := (state = 1);
at_end  := (state = 2);
to_home := (state = 3);
error   := (state = 4);

CASE state OF
0:  (* AT_HOME *)
    IF error_mode THEN state := 4;
    ELSIF reset_mode THEN
        IF NOT sensor_home THEN state := 3; END_IF;
    ELSIF run_mode AND go THEN state := 1;
    END_IF;
1:  (* TO_END -- stroke completes regardless of pause *)
    IF error_mode THEN state := 4;
    ELSIF sensor_end THEN state := 2;
    END_IF;
2:  (* AT_END -- valve held extended; only run advances to retract *)
    IF error_mode THEN state := 4;
    ELSIF reset_mode THEN state := 3;
    ELSIF run_mode THEN state := 3;
    END_IF;
3:  (* TO_HOME -- valve off, spring retracts, completes regardless of pause *)
    IF error_mode THEN state := 4;
    ELSIF sensor_home THEN state := 0;
    END_IF;
4:  (* ERROR *)
    IF reset_mode THEN
        IF sensor_home THEN state := 0; ELSE state := 3; END_IF;
    END_IF;
END_CASE;

valve_extend := (state = 1) OR (state = 2);
IF state = 4 THEN valve_extend := FALSE; END_IF;

moving := (state = 1) OR (state = 3);
stall(IN := robust AND moving, PT := t_stall);
IF stall.Q THEN
    state := 4;
    valve_extend := FALSE;
END_IF;

at_home := (state = 0);
to_end  := (state = 1);
at_end  := (state = 2);
to_home := (state = 3);
error   := (state = 4);

reset_done := Arm.at_home AND Ejector.at_home;
Panel(s1_start := Panel_S1, s2_stop := Panel_S2, s4_reset := Panel_S4,
      error_in := fault, reset_done := reset_done);

IF Panel.reset_mode OR Panel.error_mode THEN
    si := 0; grip := 0; drop := 0; vacuum := FALSE; eject_pulse := FALSE;
    IF Panel.reset_mode THEN cycles := 0; END_IF;
END_IF;

go_arm := FALSE; go_ej := FALSE; eject_pulse := FALSE;
IF Panel.run_mode AND cycles < MAG THEN
    CASE si OF
    0:  go_arm := TRUE;  IF Arm.at_end  THEN si := 1; END_IF;   (* 1 arm downstream *)
    1:  go_ej  := TRUE;  IF Ejector.at_end  THEN si := 2; END_IF; (* 2 ejector push  *)
    2:  go_arm := TRUE;  IF Arm.at_home THEN si := 3; END_IF;   (* 3 arm upstream  *)
    3:  vacuum := TRUE;  grip := grip + 1;                       (* 4 vacuum grips  *)
        IF grip >= 1 THEN grip := 0; si := 4; END_IF;
    4:  go_ej := FALSE;  IF Ejector.at_home THEN si := 5; END_IF; (* 5 ejector retract *)
    5:  go_arm := TRUE;  IF Arm.at_end  THEN si := 6; END_IF;   (* 6 arm to end    *)
    6:  eject_pulse := TRUE; vacuum := FALSE; drop := drop + 1;  (* 7 drop + vac off *)
        IF drop >= 1 THEN drop := 0; cycles := cycles + 1; si := 0; END_IF;
    END_CASE;
END_IF;

Arm(run_mode := Panel.run_mode, pause_mode := Panel.pause_mode,
    reset_mode := Panel.reset_mode, error_mode := Panel.error_mode,
    sensor_home := Station_3S1, sensor_end := Station_3S2, go := go_arm,
    t_stall := T#2s, robust := ROBUST);

Ejector(run_mode := Panel.run_mode, pause_mode := Panel.pause_mode,
    reset_mode := Panel.reset_mode, error_mode := Panel.error_mode,
    sensor_home := Station_1B1, sensor_end := Station_1B2, go := go_ej,
    t_stall := T#2s, robust := ROBUST);

// Robust faults (1.10): stalled actuator, piece pulled off the vacuum
// (vacuum commanded but Station_2B1 gripped-sensor lost), or arm reaching the
// magazine with it empty (Station_B4).
fault := ROBUST AND ( Arm.error OR Ejector.error
    OR (Panel.run_mode AND vacuum AND NOT Station_2B1)
    OR (Panel.run_mode AND Arm.at_home AND Station_B4 AND si <> 0) );

// ---- physical outputs ----
Station_3Y2 := Arm.valve_to_end;       // Arm_to_Subsequent (downstream)
Station_3Y1 := Arm.valve_to_home;      // Arm_to_Magazine
Station_1Y1 := Ejector.valve_extend;   // Magazine_Eject
Station_2Y1 := vacuum      AND NOT Panel.error_mode;   // Vacuum_On
Station_2Y2 := eject_pulse AND NOT Panel.error_mode;   // Ejector_Pulse_On
Station_H1  := Panel.start_light;      // start light
Station_H2  := Panel.reset_light;      // reset light
Panel_H3    := (cycles >= MAG);        // Q1  batch of 5 complete
Panel_H4    := Panel.error_mode;       // Q2  error
// IP_FI (succeeding-station-free) is jumpered TRUE stand-alone; for the
// integrated line (L.2) gate step 6 delivery on IP_FI.
